  ('402fe4e4-06b6-5965-8c23-87890ff0aaeb', '1396060f-5555-5ed7-a918-43972de6ad68', 'Army', 'enlisted', '35F', null, 'skills', 'E-7', null, 'SFC - Senior Intelligence Sergeant (SL4) — Skills', 'Chapter 4. Military Occupational Specialty 35F, Intelligence Analyst', 'In addition to performing duties in the preceding skill level, the Senior Intelligence Sergeant executes and manages missions while training and leading subordinate NCOs. They direct All Source Intelligence operations, develop the IA plan, and evaluate All Source Intelligence training.', '7bb4a9947945edafa1327f74347e8dbc089b6b85d82dec62211e2c690b8e5c67', 9, 9, null, 70, null, null, false, null),
  ('c34177c8-b3e2-5280-9ada-756ac39e01b2', '1396060f-5555-5ed7-a918-43972de6ad68', 'Army', 'enlisted', '35F', null, 'assignments', 'E-7', null, 'SFC - Senior Intelligence Sergeant (SL4) — KD Assignments', 'Chapter 4. Military Occupational Specialty 35F, Intelligence Analyst', '• Platoon Sergeant • NCOIC • Detachment Sergeant • Senior Enlisted Advisor/Leader (SEA/SEL)', '57017e909ea06ffdced429a07c7426b3cbb21aea84b803379e174998da39c3bb', 9, 9, null, 71, null, null, false, null),
