  ('7f967fec-1db6-5cec-8faf-d465926a95cd', '1396060f-5555-5ed7-a918-43972de6ad68', 'Army', 'enlisted', '35F', null, 'assignments', 'E-7', null, 'SFC - Senior Intelligence Sergeant (SL4) — Broadening Assignments (*When available to AGR)', 'Chapter 4. Military Occupational Specialty 35F, Intelligence Analyst', '• Senior Drill Sergeant* • Senior Instructor/SGL • Recruiter* • Career Management NCO • Talent Management NCO • Training Developer/Writer • OC/T • Defense Attaché* • Capability Developer • Inspector General (IG) NCO • Equal Opportunity Advisor (EOA)', '31446cbe6598e03d759bfbf82b8111b4f1ad7b9520acb8f7b69c98663da71538', 9, 10, null, 73, null, null, false, null),
