  ('e1e77820-1910-5d54-85ff-c960447ee3ca', '1396060f-5555-5ed7-a918-43972de6ad68', 'Army', 'enlisted', '35P', null, 'assignments', 'E-7', null, 'SFC – Senior SIGINT Voice Interceptor (SL4) — Broadening Assignments (*When available to AGR)', 'Chapter 14. MOS 35P, SIGINT Voice Interceptor', '• Senior Drill Sergeant* • Senior Instructor/SGL • Recruiter • OC/T* • Chief MLI* • Training Developer* • Career Management NCO* • Talent Management NCO* • DTRA Linguist* • IG NCO • EOA • BDE CLPM • Defense Attaché*', '8649dc8d157f636752e3de52738069dc6da67b7671226d13163e3ad007d87f55', 37, 37, null, 177, null, null, false, null),
